func:
// SITE SETTINGS: the settings of this flow only (site name, dry run).
// In: any message from an inject node. Out: the same message.
// It reads the site from the Config tab (global context), copies the
// shared settings into flow context and builds the three file paths.
var SITE_NAME = 'Hull';
// true = log row counts, write NO files. false = write the tables.
var DRY_RUN = false;
// Schedule: yesterday plus this many days before it.
var REBUILD_DAYS = 2;
// Folder prefix of the site folder: pbi_plan_opt/<prefix><site>/...
var FOLDER_PREFIX = 'site=';

var shared = glob.get('cfg');
if (!shared) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not run'
  });
  node.error('global cfg is missing: deploy or run the Config tab first');
  return null;
}
var matches = shared.sites.filter(function (s) {
  return s.name === SITE_NAME;
});
if (!matches.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'site not in CONFIG'
  });
  node.error('site "' + SITE_NAME + '" is not in the CONFIG sites list');
  return null;
}
var site = matches[0];
if (!site.assetIds.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no assets'
  });
  node.error('site "' + SITE_NAME + '" has no assetIds in CONFIG');
  return null;
}

var cfg = Object.assign({}, shared);
cfg.site = site.name;
cfg.dayStartHour = site.dayStartHour;
cfg.assetIds = site.assetIds;
cfg.dryRun = DRY_RUN;
cfg.rebuildDays = REBUILD_DAYS;
var folder = FOLDER_PREFIX + site.name;
// YYYY-MM-DD becomes the production day.
cfg.paths = {
  pbi_plan_opt: shared.root + '/pbi_plan_opt/' + folder +
    '/pbi_plan_opt_YYYY-MM-DD.parquet',
  pbi_time_utilisation: shared.root + '/pbi_time_utilisation/' + folder +
    '/pbi_time_utilisation_YYYY-MM-DD.parquet',
  pbi_daily_losses: shared.root + '/pbi_daily_losses/' + folder +
    '/pbi_daily_losses_YYYY-MM-DD.parquet'
};
flow.set('cfg', cfg);

node.status({
  fill: DRY_RUN ? 'yellow' : 'green',
  shape: 'dot',
  text: SITE_NAME + (DRY_RUN ? ' DRY RUN' : ' WRITE MODE')
});
return msg;

// Builds the list of production days. One message leaves per day, oldest first.
// In: the schedule inject (any payload) or the backfill inject
// {start, end}. Out: {topic: 'day', payload: 'YYYY-MM-DD', mode}.
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var cfg = flow.get('cfg');
// A production day D runs from D start hour to D+1 start hour (UTC).
var PRODUCTION_DAY_START_HOURS = cfg.dayStartHour;
var p = msg.payload;
var days = [];
var mode;

function dayStr(ms) {
  return new Date(ms).toISOString().slice(0, 10);
}

if (p && typeof p === 'object' && p.start && p.end) {
  mode = 'backfill';
  var s = Date.parse(p.start + 'T00:00:00Z');
  var e = Date.parse(p.end + 'T00:00:00Z');
  if (isNaN(s) || isNaN(e) || e < s) {
    node.error(
      'Backfill needs {"start":"YYYY-MM-DD","end":"YYYY-MM-DD"} ' +
        'with start <= end',
      msg
    );
    return null;
  }
  for (var t = s; t <= e; t += DAY_MS) {
    days.push(dayStr(t));
  }
} else {
  mode = 'schedule';
  var now = Date.now();
  // One hour after the day start the latest finished production day is the
  // one before the current one.
  var shifted = now - PRODUCTION_DAY_START_HOURS * HOUR_MS - DAY_MS;
  var latest = Date.parse(dayStr(shifted) + 'T00:00:00Z');
  for (var i = cfg.rebuildDays; i >= 0; i--) {
    days.push(dayStr(latest - i * DAY_MS));
  }
}

var text = mode + ': ' + days.length + ' day(s) ' + days[0];
if (days.length > 1) {
  text += ' .. ' + days[days.length - 1];
}
node.status({ fill: 'blue', shape: 'dot', text: text });
var messages = days.map(function (d) {
  return { topic: 'day', payload: d, mode: mode };
});
return [messages];

// Builds the token request. The next node is an http request node.
// In: a day message {payload: 'YYYY-MM-DD', mode}.
// Out: msg.method, msg.url, msg.headers (and a form body on xcelerator).
var cfg = flow.get('cfg');
var credentials = cfg.clientId + ':' + cfg.clientSecret;
msg.day = msg.payload;
msg.loadedAt = Date.now();
msg.method = 'POST';
msg.url = cfg.tokenUrl;
msg.headers = {
  'Authorization': 'Basic ' + Buffer.from(credentials).toString('base64'),
  'Accept': 'application/json'
};
if (cfg.tokenForm) {
  msg.headers['Content-Type'] = 'application/x-www-form-urlencoded';
  msg.payload = 'grant_type=client_credentials';
} else {
  delete msg.payload;
}
return msg;

// Keeps the token and builds the OEE asset list request (isConfigured,
// isManual). In: the token response. Out 1: the request for the http node.
// Out 2: a log message when the token request failed.
var cfg = flow.get('cfg');
var token = msg.payload && msg.payload.access_token;

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !token) {
  var failed = 'FAILED, NOTHING WRITTEN: token request failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}
msg.token = token;
msg.method = 'GET';
msg.url = cfg.oeeBase + '/assets';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Chooses the assets to read for the day.
// In: the OEE asset list. Out 1: msg.payload = [{id, isManual, name}] for
// the split node. Out 2: a log message when nothing can be read.
var cfg = flow.get('cfg');
var byId = {};
var skipped = [];
var targets = [];

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
  var failed = 'FAILED, NOTHING WRITTEN: OEE asset list failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}

var oee = msg.payload;
oee.forEach(function (o) {
  byId[o.assetId] = o;
});
var ids = cfg.assetIds;
if (!ids || !ids.length) {
  ids = oee.map(function (o) {
    return o.assetId;
  });
}
ids.forEach(function (id) {
  var o = byId[id];
  if (!o) {
    skipped.push(String(id).slice(0, 6) + '... not an OEE asset');
    return;
  }
  if (o.isConfigured === false) {
    skipped.push(o.name + ' not configured');
    return;
  }
  targets.push({ id: id, isManual: o.isManual, name: o.name });
});
msg.planSkipped = skipped;

if (!targets.length) {
  var nothing = 'NOTHING TO WRITE (no assets to read)';
  if (skipped.length) {
    nothing += ' | skipped: ' + skipped.join('; ');
  }
  return [null, logMessage(nothing)];
}
msg.payload = targets;
node.status({
  fill: 'blue',
  shape: 'dot',
  text: msg.day + ': ' + targets.length + ' asset(s)'
});
return [msg, null];

// Builds the Asset Management request for one asset (to get hierarchyPath).
// In: one asset {id, isManual, name} from the split node.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
msg.asset = msg.payload;
msg.method = 'GET';
msg.url = cfg.amBase + '/assets/' +
  encodeURIComponent(msg.asset.id);
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/hal+json'
};
delete msg.payload;
return msg;

// Works out the asset hierarchy and builds the evaluateKPIs request.
// In: the Asset Management response. Out 1: the KPI request.
// Out 2: the asset result for the join when the asset failed or is excluded.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;

// Names are root first. Tenant layout: [0] tenant, [1] region, [2] site,
// [3] area, [4] line, [5] machine. GT4 has no machine, so it is the line.
function hierarchyFromNames(names) {
  return {
    asset_name: names[names.length - 1] || null,
    site: names[2] || null,
    area: names[3] || null,
    line: names[4] || null,
    machine: names[5] || null
  };
}

function toJoin(note) {
  msg.payload = {
    assetId: msg.asset.id,
    name: msg.asset.name,
    failed: note.failed || null,
    skipped: note.skipped || null,
    kpiRows: [],
    lossRows: []
  };
  return [null, msg];
}

var details = msg.payload;
if (msg.statusCode !== 200 || !details || !details.name) {
  return toJoin({
    failed: msg.asset.name + ': asset details failed, HTTP ' + msg.statusCode
  });
}

var names = (details.hierarchyPath || []).map(function (p) {
  return p.name;
});
names.push(details.name);
msg.h = hierarchyFromNames(names);
var excluded = cfg.excludeNames.indexOf(details.name) >= 0;
var parentExcluded = names.slice(0, -1).some(function (n) {
  return cfg.excludeAncestorNames.indexOf(n) >= 0;
});
if (excluded || parentExcluded) {
  return toJoin({ skipped: msg.h.asset_name + ' excluded' });
}

// A production day D runs from D start hour to D+1 start hour (UTC).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
msg.method = 'POST';
msg.url = cfg.oeeBase + '/expressions/evaluateKPIs';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Content-Type': 'application/json',
  'Accept': 'application/json'
};
msg.payload = {
  assetId: msg.asset.id,
  scope: {
    from: new Date(from).toISOString(),
    to: new Date(from + DAY_MS).toISOString(),
    filter: [{ key: 'PRODUCT', value: [] }],
    recursive: false,
    groupedByDateTime: true
  }
};
return [msg, null];

// Checks the evaluateKPIs response of one asset.
// In: the response. Out 1: the same message when it holds KPI results.
// Out 2: the asset result for the join when the call failed, the asset
// configuration is not finished or there is no data.
var name = msg.h.asset_name;
var body = msg.payload;

function toJoin(note) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: note.failed || null,
    skipped: note.skipped || null,
    kpiRows: [],
    lossRows: []
  };
  return [null, msg];
}

var notFinished = msg.statusCode === 400 &&
  /configuration not finished/i.test(JSON.stringify(body));
if (notFinished) {
  return toJoin({ skipped: name + ' configuration not finished' });
}
// Short text of the API error (errors[0].message), else the raw body.
function apiMessage(payload) {
  var list = payload && (payload.errors ||
    (payload.data && payload.data.errors));
  if (list && list.length && list[0].message) {
    return String(list[0].message);
  }
  return JSON.stringify(payload).slice(0, 200);
}

if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  var why = msg.statusCode === 200 ? '' : ': ' + apiMessage(body);
  return toJoin({
    failed: name + ': evaluateKPIs failed, HTTP ' + msg.statusCode + why
  });
}
if (!body.results || !body.results.length) {
  return toJoin({ skipped: name + ' no data' });
}
return [msg, null];

// Pivots the evaluateKPIs response to one entry per hour.
// In: the response (msg.payload.results, checked in node 3.3).
// Out: msg.hours = [{time, values}] oldest hour first, msg.kpiMeta and
// msg.unmapped (KPI names that have no column).

// KPI name in Insights Hub -> column name in fact_kpi.
var KPI_COLUMNS = {
  'Good parts': 'good_parts',
  'Total parts': 'total_parts',
  'Rejected parts': 'rejected_parts',
  'Connected rejected parts': 'connected_rejected_parts',
  'Manual rejected parts': 'manual_rejected_parts',
  'Theoretical output': 'theoretical_output',
  'Quality': 'quality',
  'Performance': 'performance',
  'Availability': 'availability',
  'OEE': 'oee',
  'TEEP': 'teep',
  'Total time': 'total_time_ms',
  'Planned stops': 'planned_stops_ms',
  'Planned stop from shift plan': 'planned_stop_shift_plan_ms',
  'Operational time': 'operational_time_ms',
  'Net production time': 'net_production_time_ms',
  'Net operational time': 'net_operational_time_ms',
  'Used operational time': 'used_operational_time_ms',
  'Availability losses': 'availability_losses_ms',
  'Availability loss (occurrence)': 'availability_loss_count',
  'Performance losses': 'performance_losses_ms',
  'Quality losses': 'quality_losses_ms',
  'MTTR': 'mttr_ms',
  'MTBF': 'mtbf_ms',
  'Downtime (duration)': 'downtime_ms',
  'Downtimes (occurrence)': 'downtime_count',
  'Micro stops (duration)': 'micro_stops_ms',
  'Micro stops (occurrence)': 'micro_stops_count',
  'Macro stops (duration)': 'macro_stops_ms',
  'Macro stops (occurrence)': 'macro_stops_count'
};
// Columns that are rounded to whole numbers. All others keep their decimals.
var INT_COLUMNS = [
  'total_time_ms',
  'planned_stops_ms',
  'planned_stop_shift_plan_ms',
  'operational_time_ms',
  'net_production_time_ms',
  'availability_losses_ms',
  'micro_stops_ms',
  'micro_stops_count',
  'macro_stops_ms'
];
// These columns come first in every row.
var RATIO_COLUMNS = [
  'oee',
  'teep',
  'availability',
  'performance',
  'quality'
];

function numOrNull(v) {
  if (v === null || v === undefined || v === '') {
    return null;
  }
  var n = Number(v);
  return isFinite(n) ? n : null;
}

// Collect the value of every KPI per hour.
var body = msg.payload;
var unmapped = [];
var byHour = {};
var times = [];
body.results.forEach(function (r) {
  var col = KPI_COLUMNS[r.name];
  if (!col) {
    if (unmapped.indexOf(r.name) < 0) {
      unmapped.push(r.name);
    }
    return;
  }
  (r.groups || []).forEach(function (g) {
    if (!byHour[g.time]) {
      byHour[g.time] = {};
      times.push(g.time);
    }
    byHour[g.time][col] = numOrNull(g.value);
  });
});

// One entry per hour with every column present (null when missing).
msg.hours = times.sort().map(function (t) {
  var hour = byHour[t];
  var values = {};
  RATIO_COLUMNS.forEach(function (c) {
    values[c] = hour[c] === undefined ? null : hour[c];
  });
  Object.keys(KPI_COLUMNS).forEach(function (k) {
    var c = KPI_COLUMNS[k];
    if (values.hasOwnProperty(c)) {
      return;
    }
    var x = hour[c] === undefined ? null : hour[c];
    var rounded = x !== null && INT_COLUMNS.indexOf(c) >= 0;
    values[c] = rounded ? Math.round(x) : x;
  });
  return { time: t, values: values };
});

var missing = null;
if (body.missingMapping && body.missingMapping.length) {
  missing = JSON.stringify(body.missingMapping);
}
msg.kpiMeta = {
  productUnit: body.productUnit || null,
  missingMapping: missing
};
msg.unmapped = unmapped;
delete msg.payload;
return msg;

// Builds the OEE config request of one asset (to get its calendar id).
// In: msg.asset and msg.token, after the KPI steps. msg.hours is kept.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
msg.method = 'GET';
msg.url = cfg.oeeBase + '/assets/' +
  encodeURIComponent(msg.asset.id) + '/config';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Saves the calendar and product collection ids, builds the events request.
// In: the OEE config response. Out 1: the calendarEvents request. Out 2:
// the asset result for the join when the config call failed or the asset
// has no calendar (no half days).
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var name = msg.h.asset_name;

function toJoin(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  return [null, msg];
}

var config = msg.payload || {};
if (msg.statusCode !== 200) {
  return toJoin(name + ': asset config failed, HTTP ' + msg.statusCode);
}
if (!config.calendarId) {
  return toJoin(name + ': asset has no calendar id');
}

// The events that cover the production day D (D start hour to D+1).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
msg.calendarId = config.calendarId;
msg.productCollectionId = config.productCollectionId || null;
msg.method = 'GET';
msg.url = cfg.oeeBase + '/calendars/' +
  encodeURIComponent(config.calendarId) + '/calendarEvents' +
  '?from=' + new Date(from).toISOString() +
  '&to=' + new Date(from + DAY_MS).toISOString();
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Turns the calendar events into shift rules.
// In: the calendarEvents response. Out 1: msg.shiftRules = [{name, freq,
// interval, start, until, duration}] (epoch ms, null when open ended).
// Out 2: the asset result for the join when the call failed.
var name = msg.h.asset_name;
var events = msg.payload && msg.payload.calendarEvents;

if (msg.statusCode !== 200 || !Array.isArray(events)) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: name + ': calendar events failed, HTTP ' + msg.statusCode,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  return [null, msg];
}

// Date text to epoch ms, null when missing or not a date.
function toMs(text) {
  var ms = Date.parse(text);
  return isNaN(ms) ? null : ms;
}

// An event without a recurrence object gets freq null and never matches.
msg.shiftRules = events.map(function (e) {
  var rule = e.rrule;
  if (!rule || typeof rule !== 'object') {
    rule = {};
  }
  return {
    name: e.name || null,
    freq: rule.freq || null,
    interval: rule.interval || null,
    start: toMs(rule.dtstart),
    until: toMs(rule.until),
    duration: Math.round(Number(e.duration))
  };
});
delete msg.payload;
return [msg, null];

// Builds the filterValues request: the products and orders of the day.
// In: msg.asset, msg.token and msg.day after the shift steps.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;

// A production day D runs from D start hour to D+1 start hour (UTC).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var url = cfg.oeeBase + '/assets/';
url += encodeURIComponent(msg.asset.id) + '/filterValues';
url += '?from=' + new Date(from).toISOString();
url += '&to=' + new Date(from + DAY_MS).toISOString();

msg.method = 'GET';
msg.url = url;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Reads the filterValues answer and asks for the product list.
// In: the filterValues response. Out 1: the product list request. Out 2:
// no product collection, go on. Out 3: no product or order that day.
// Out 4: the asset result for the join when the call failed.
var cfg = flow.get('cfg');
var name = msg.h.asset_name;
// More values than this in one day fail the asset (one KPI call each).
var MAX_VALUES = 30;

function toJoin(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  delete msg.shiftRules;
  return [null, null, null, msg];
}

// The values of one filter key, text only, every value once.
function valuesOf(list, key) {
  var found = list.filter(function (f) {
    return f.key === key;
  })[0];
  var seen = [];
  ((found && found.value) || []).forEach(function (v) {
    var text = String(v);
    if (text !== '' && seen.indexOf(text) < 0) {
      seen.push(text);
    }
  });
  return seen;
}

var body = msg.payload;
if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  return toJoin(name + ': filterValues failed, HTTP ' + msg.statusCode);
}
var list = body.filterValues || [];
var products = valuesOf(list, 'product');
var orders = valuesOf(list, 'order');
if (products.length > MAX_VALUES || orders.length > MAX_VALUES) {
  return toJoin(name + ': more than ' + MAX_VALUES + ' products or orders');
}
msg.values = {
  products: products,
  orders: orders
};
delete msg.payload;
if (!products.length && !orders.length) {
  return [null, null, msg, null];
}
if (!msg.productCollectionId) {
  msg.productsCalled = false;
  return [null, msg, null, null];
}

msg.productsCalled = true;
var url = cfg.oeeBase + '/productCollections/';
url += encodeURIComponent(msg.productCollectionId) + '/products';
msg.method = 'GET';
msg.url = url;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
return [msg, null, null, null];

// Keeps the products of the day and sends one message per product and
// per order. In: the product list response (or none). Out 1: one message
// per value. Out 2: nothing to ask. Out 3: asset result for the join.
var STALE_MS = 21600000;
var MIN_PER = {
  SECOND: 60,
  MINUTE: 1,
  HOUR: 1 / 60,
  DAY: 1 / 1440
};
var name = msg.h.asset_name;

function toJoin(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  delete msg.shiftRules;
  return [null, null, msg];
}

// Parts per minute of a product, null when the interval is not known.
function perMinute(p) {
  var factor = MIN_PER[String(p.designSpeedInterval).toUpperCase()];
  var value = Number(p.designSpeedValue);
  if (factor === undefined || !isFinite(value) || p.designSpeedValue === null) {
    return null;
  }
  return value * factor;
}

// Step 1: keep the master data of the products that ran that day.
var wanted = msg.values.products;
msg.productList = [];
if (msg.productsCalled) {
  var body = msg.payload;
  if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
    return toJoin(name + ': product list failed, HTTP ' + msg.statusCode);
  }
  var all = Array.isArray(body) ? body : body.products || [];
  all.forEach(function (p) {
    if (wanted.indexOf(String(p.name)) < 0) {
      return;
    }
    msg.productList.push({
      name: String(p.name),
      code: p.code ? String(p.code) : null,
      description: p.description ? String(p.description) : null,
      perMinute: perMinute(p)
    });
  });
}
delete msg.payload;
delete msg.productsCalled;

// Step 2: one job per product and per order.
var jobs = [];
msg.values.products.forEach(function (v) {
  jobs.push({ key: 'PRODUCT', value: v });
});
msg.values.orders.forEach(function (v) {
  jobs.push({ key: 'ORDER', value: v });
});
if (!jobs.length) {
  return [null, msg, null];
}

// Step 3: forget runs that never finished, then clone one message per job.
var now = Date.now();
var runs = flow.get('valueRuns') || {};
Object.keys(runs).forEach(function (k) {
  if (now - runs[k].created > STALE_MS) {
    delete runs[k];
  }
});
flow.set('valueRuns', runs);
var run = msg.asset.id + '|' + msg.day + '|' + now + '|';
run += Math.floor(Math.random() * 1000000);
var out = jobs.map(function (job) {
  var copy = JSON.parse(JSON.stringify(msg));
  copy.job = job;
  copy.jobRun = run;
  copy.jobCount = jobs.length;
  return copy;
});
return [out, null, null];

// Builds the evaluateKPIs request of ONE product or order of the day.
// In: msg.job = {key: PRODUCT or ORDER, value}, msg.asset, msg.day.
// Out: the same POST as 3.2, filtered on that value, hourly.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;

function filterFor(key) {
  return { key: key, value: msg.job.key === key ? [msg.job.value] : [] };
}

msg.method = 'POST';
msg.url = cfg.oeeBase + '/expressions/evaluateKPIs';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Content-Type': 'application/json',
  'Accept': 'application/json'
};
msg.payload = {
  assetId: msg.asset.id,
  scope: {
    from: new Date(from).toISOString(),
    to: new Date(from + DAY_MS).toISOString(),
    filter: [
      filterFor('PRODUCT'),
      filterFor('ORDER'),
      { key: 'SHIFT', value: [] }
    ],
    recursive: false,
    groupedByDateTime: true
  }
};
return msg;

// Collects the hours of every product and order of one asset and day.
// In: one filtered evaluateKPIs response (msg.job, msg.jobRun, jobCount).
// Out 1: when all are in, the asset message with msg.valueHours. Out 2:
// the asset result for the join when one of the calls failed.
var name = msg.h.asset_name;
var runs = flow.get('valueRuns') || {};
var run = runs[msg.jobRun];
if (!run) {
  run = {
    created: Date.now(),
    done: 0,
    failed: [],
    hours: { PRODUCT: {}, ORDER: {} }
  };
  runs[msg.jobRun] = run;
}
run.done += 1;

// An hour belongs to the value when it has parts (total, else good).
function partsOf(results) {
  var wanted = ['Total parts', 'Good parts'];
  var found = null;
  wanted.forEach(function (n) {
    (results || []).forEach(function (r) {
      if (r.name === n && !found) {
        found = r;
      }
    });
  });
  return found;
}

var label = msg.job.key + ' ' + msg.job.value;
var body = msg.payload;
if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  run.failed.push(label + ' HTTP ' + msg.statusCode);
} else {
  var parts = partsOf(body.results);
  var hours = [];
  ((parts && parts.groups) || []).forEach(function (g) {
    if (Number(g.value) > 0) {
      hours.push(Date.parse(g.time));
    }
  });
  run.hours[msg.job.key][msg.job.value] = hours;
}

if (run.done < msg.jobCount) {
  flow.set('valueRuns', runs);
  return null;
}
delete runs[msg.jobRun];
flow.set('valueRuns', runs);
delete msg.job;
delete msg.jobRun;
delete msg.jobCount;
delete msg.payload;
if (run.failed.length) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: name + ': value KPIs failed, ' + run.failed[0],
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  delete msg.shiftRules;
  return [null, msg];
}
msg.valueHours = run.hours;
return [msg, null];

// Gives every hour of the day a product and an order.
// In: msg.hours, msg.valueHours, msg.productList (absent when no values).
// Out: hour.product and hour.order on every hour, and msg.hourInfo (hour
// start in ms -> product and order) for the stop rows.
var valueHours = msg.valueHours || { PRODUCT: {}, ORDER: {} };
var master = msg.productList || [];

// The value (a product name or an order) that has parts in this hour.
function valueAt(kind, ms) {
  var names = Object.keys(valueHours[kind]);
  var found = null;
  names.forEach(function (n) {
    if (found === null && valueHours[kind][n].indexOf(ms) >= 0) {
      found = n;
    }
  });
  return found;
}

// An hour without parts takes the value of the hour before it. Hours
// before the first value take the first value that follows.
function fill(list) {
  var last = null;
  list.forEach(function (item, i) {
    if (item === null) {
      list[i] = last;
    } else {
      last = item;
    }
  });
  var next = null;
  for (var i = list.length - 1; i >= 0; i--) {
    if (list[i] === null) {
      list[i] = next;
    } else {
      next = list[i];
    }
  }
  return list;
}

// Part name: the description when there is one, else the name. The key is
// the product code, else the name.
function productOf(productName) {
  if (productName === null) {
    return null;
  }
  var record = master.filter(function (p) {
    return p.name === productName;
  })[0];
  var rec = record || {};
  return {
    part_name: rec.description || productName,
    product_key: rec.code || productName,
    per_minute: rec.perMinute === undefined ? null : rec.perMinute
  };
}

var times = msg.hours.map(function (h) {
  return Date.parse(h.time);
});
var products = fill(times.map(function (ms) {
  return valueAt('PRODUCT', ms);
}));
var orders = fill(times.map(function (ms) {
  return valueAt('ORDER', ms);
}));

msg.hourInfo = {};
msg.hours.forEach(function (hour, i) {
  hour.product = productOf(products[i]);
  hour.order = orders[i];
  msg.hourInfo[String(times[i])] = {
    product: hour.product,
    order: hour.order
  };
});
delete msg.valueHours;
delete msg.productList;
delete msg.values;
return msg;

// Builds the Power BI rows of one asset and day from the hourly KPIs:
// pbi_plan_opt (per shift and product), pbi_time_utilisation (per day).
// In: msg.hours (with hour.product), msg.shiftRules, msg.h.
// Out: msg.planRows, msg.utilRows.
var MIN_MS = 60000;
var DAY_MS = 86400000;
var MINUTES_PER_DAY = 1440;
var loadedAt = msg.loadedAt || Date.now();

// The shift of an instant: the event whose recurrence covers it, else null.
function shiftOf(ms) {
  var found = null;
  msg.shiftRules.forEach(function (rule) {
    if (found) {
      return;
    }
    var days = 0;
    if (rule.freq === 'DAILY') {
      days = 1;
    } else if (rule.freq === 'WEEKLY') {
      days = 7;
    }
    var until = rule.until === null ? Infinity : rule.until;
    if (!days || rule.start === null || ms < rule.start || ms > until) {
      return;
    }
    var step = days * rule.interval * DAY_MS;
    var occurrence = rule.start + Math.floor((ms - rule.start) / step) * step;
    if (ms < occurrence + rule.duration) {
      found = rule.name;
    }
  });
  return found;
}

// Adds a value to a sum. A sum with no value at all stays null.
function addTo(sum, key, value) {
  if (value === null || value === undefined) {
    return;
  }
  sum[key] = (sum[key] || 0) + value;
}

function minutes(ms) {
  return ms === null || ms === undefined ? null : ms / MIN_MS;
}

function sumOrNull(sum, key) {
  return sum[key] === undefined ? null : sum[key];
}

var groups = {};
var order = [];
msg.hours.forEach(function (hour) {
  var shift = shiftOf(Date.parse(hour.time));
  var product = hour.product || null;
  var key = String(shift) + '|' + String(product && product.product_key);
  var g = groups[key];
  if (!g) {
    g = {
      shift: shift,
      product: product,
      sum: {},
      hours: 0
    };
    groups[key] = g;
    order.push(key);
  }
  var v = hour.values;
  g.hours += 1;
  addTo(g.sum, 'good', v.good_parts);
  var planned = v.planned_stop_shift_plan_ms;
  if (v.total_time_ms !== null && planned !== null) {
    addTo(g.sum, 'total', minutes(v.total_time_ms - planned));
  }
  addTo(g.sum, 'opt', minutes(v.operational_time_ms));
  addTo(g.sum, 'oee', minutes(v.used_operational_time_ms));
  addTo(g.sum, 'down', minutes(v.downtime_ms));
});

// Parts that fit in a time at the design speed. Null without a speed.
function unitsOf(g, minutesKey) {
  var perMinute = g.product && g.product.per_minute;
  var time = g.sum[minutesKey];
  if (perMinute === null || perMinute === undefined || time === undefined) {
    return null;
  }
  return perMinute * time;
}

var daySum = {};
msg.planRows = order.map(function (key) {
  var g = groups[key];
  addTo(daySum, 'total', g.sum.total);
  addTo(daySum, 'opt', g.sum.opt);
  addTo(daySum, 'oee', g.sum.oee);
  return {
    site_name: msg.h.site,
    area_name: msg.h.area,
    machine_name: msg.h.asset_name,
    unique_machine_name: msg.asset.id,
    date: msg.day,
    shift_name: g.shift,
    part_name: g.product ? g.product.part_name : null,
    product_key: g.product ? g.product.product_key : null,
    good_parts: sumOrNull(g.sum, 'good'),
    capacity: unitsOf(g, 'opt'),
    downtime_units: unitsOf(g, 'down'),
    total_time: sumOrNull(g.sum, 'total'),
    planned_opt: sumOrNull(g.sum, 'opt'),
    oee_time: sumOrNull(g.sum, 'oee'),
    oee_target: null,
    pdt_target: null,
    updt_target: null,
    source_hours: g.hours,
    loaded_at: loadedAt
  };
});

msg.utilRows = [];
if (order.length) {
  msg.utilRows.push({
    site_name: msg.h.site,
    machine_name: msg.h.asset_name,
    unique_machine_name: msg.asset.id,
    date: msg.day,
    total_time_total: sumOrNull(daySum, 'total'),
    planned_opt_total: sumOrNull(daySum, 'opt'),
    oee_time_total: sumOrNull(daySum, 'oee'),
    all_time: MINUTES_PER_DAY,
    loaded_at: loadedAt
  });
}
delete msg.hours;
delete msg.kpiMeta;
return msg;

// Builds the downtimeReasons request for one asset and one production day.
// In: msg.kpiRows (already built). Out: msg.method, msg.url and msg.headers
// for the http request node.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
// One page of 5000 holds every stop of a day (tested: 423 stops with
// size 1000). More than one page makes the day fail in node 4.2.
var PAGE_SIZE = 5000;

// A production day D runs from D start hour to D+1 start hour (UTC).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var fromIso = new Date(from).toISOString();
var toIso = new Date(from + DAY_MS).toISOString();
var query = '?from=' + encodeURIComponent(fromIso) +
  '&to=' + encodeURIComponent(toIso) +
  '&size=' + PAGE_SIZE + '&page=0';
msg.method = 'GET';
msg.url = cfg.oeeBase + '/assets/' +
  encodeURIComponent(msg.asset.id) + '/downtimeReasons' + query;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
return msg;

// Checks the downtimeReasons response of one asset.
// In: the response. Out 1: msg.stops = the list of stops.
// Out 2: the asset result for the join when the call failed or has more
// than one page. The KPI rows of the asset are dropped then (no half days).
var name = msg.h.asset_name;

function failedResult(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    kpiRows: [],
    lossRows: [],
    unmapped: msg.unmapped
  };
  delete msg.kpiRows;
  delete msg.unmapped;
  return [null, msg];
}

var body = msg.payload;
// Short text of the API error (errors[0].message), else the raw body.
function apiMessage(payload) {
  var list = payload && (payload.errors ||
    (payload.data && payload.data.errors));
  if (list && list.length && list[0].message) {
    return String(list[0].message);
  }
  return JSON.stringify(payload).slice(0, 200);
}

if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  var why = msg.statusCode === 200 ? '' : ': ' + apiMessage(body);
  return failedResult(
    name + ': downtimeReasons failed, HTTP ' + msg.statusCode + why
  );
}
if (body.page && body.page.totalPages > 1) {
  return failedResult(
    name + ': downtimeReasons has more than one page (' +
      body.page.totalElements + ' rows), raise PAGE_SIZE in node 4.1'
  );
}

msg.stops = (body._embedded && body._embedded.downtimeReasons) || [];
delete msg.payload;
return [msg, null];

// Builds the pbi_daily_losses rows of one asset: one row per stop.
// In: msg.stops, msg.shiftRules, msg.hourInfo, msg.h. Out: msg.lossRows and
// msg.droppedStops. Product and order come from the hour of the stop.
// Targets and volume total have no data yet and are null.
var MIN_MS = 60000;
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var cfg = flow.get('cfg');
// The reason a stop gets when nobody chose one.
var DEFAULT_REASON = 'Unplanned Downtime';
var BREAKDOWN_CATEGORY = 'Breakdown';
var loadedAt = msg.loadedAt || Date.now();
// A production day D runs from D dayStartHour UTC to D+1 dayStartHour.
var midnight = Date.parse(msg.day + 'T00:00:00.000Z');
var fromMs = midnight + cfg.dayStartHour * HOUR_MS;
var toMs = fromMs + DAY_MS;
var month = msg.day.slice(0, 7);

// The shift of an instant: the event whose recurrence covers it, else null.
function shiftOf(ms) {
  var found = null;
  msg.shiftRules.forEach(function (rule) {
    if (found) {
      return;
    }
    var days = 0;
    if (rule.freq === 'DAILY') {
      days = 1;
    } else if (rule.freq === 'WEEKLY') {
      days = 7;
    }
    var until = rule.until === null ? Infinity : rule.until;
    if (!days || rule.start === null || ms < rule.start || ms > until) {
      return;
    }
    var step = days * rule.interval * DAY_MS;
    var occurrence = rule.start + Math.floor((ms - rule.start) / step) * step;
    if (ms < occurrence + rule.duration) {
      found = rule.name;
    }
  });
  return found;
}

// Last Sunday of the month at 01:00 UTC. The month is 0-based.
function lastSundayUtc(year, monthIndex) {
  var d = new Date(Date.UTC(year, monthIndex + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d.getTime();
}

// Europe/London offset in hours (UK sites only).
function londonOffsetHours(ms) {
  var year = new Date(ms).getUTCFullYear();
  var inBst = ms >= lastSundayUtc(year, 2) && ms < lastSundayUtc(year, 9);
  return inBst ? 1 : 0;
}

function numOrNull(v) {
  if (v === null || v === undefined || v === '') {
    return null;
  }
  var n = Number(v);
  return isFinite(n) ? n : null;
}

function lossGroup(category, reason) {
  if (cfg.plannedRoots.indexOf(category) >= 0) {
    return 'Planned Loss';
  }
  if (reason === DEFAULT_REASON) {
    return 'Not Logged';
  }
  return 'Unplanned Loss';
}

// Only stops that start inside the production day are kept.
var hourInfo = msg.hourInfo || {};
var lossRows = [];
var dropped = 0;
msg.stops.forEach(function (r) {
  var start = Date.parse(r.from);
  if (!(start >= fromMs && start < toMs)) {
    dropped++;
    return;
  }
  var parts = r.reasonFullPath ? String(r.reasonFullPath).split(' / ') : [];
  var category = parts.length > 1 ? parts[0] : null;
  var subgroup = parts.length > 2 ? parts[1] : null;
  var localMs = start + londonOffsetHours(start) * HOUR_MS;
  var localIso = new Date(localMs).toISOString();
  var duration = numOrNull(r.duration);
  var minutes = duration === null ? null : Math.round(duration) / MIN_MS;
  var info = hourInfo[String(Math.floor(start / HOUR_MS) * HOUR_MS)] || {};
  var product = info.product || {};
  var perMinute = product.per_minute;
  var units = null;
  if (minutes !== null && perMinute !== null && perMinute !== undefined) {
    units = minutes * perMinute;
  }
  lossRows.push({
    site_name: msg.h.site,
    machine_name: msg.h.asset_name,
    unique_machine_name: msg.asset.id,
    date: localIso.slice(0, 10),
    time: localIso.slice(11, 19),
    shift_start_date: msg.day,
    shift_name: shiftOf(start),
    duration: minutes,
    loss_units: units,
    loss_lvl3_group: lossGroup(category, r.reason || null),
    loss_lvl3_sub_group: category,
    loss_lvl3_desc: r.reason || null,
    loss_final_level: r.reason || null,
    equipment: subgroup,
    breakdown_types: category === BREAKDOWN_CATEGORY ? subgroup : null,
    batch_id: info.order || null,
    comment_count: numOrNull(r.commentCount),
    part_name: product.part_name || null,
    product_key: product.product_key || null,
    loss_target_key: msg.h.line + '|' + category + '|' + localIso.slice(0, 7),
    value: null,
    target: null,
    volume_key: msg.h.line + '|' + localIso.slice(0, 7),
    volume_total: null,
    loaded_at: loadedAt
  });
});

msg.lossRows = lossRows;
msg.droppedStops = dropped;
delete msg.stops;
delete msg.hourInfo;
return msg;

// Builds the result of one asset and hands it to the join.
// In: msg.planRows, utilRows, lossRows, droppedStops and unmapped.
// Out: msg.payload = {assetId, name, failed, skipped, planRows, utilRows,
// lossRows, unmapped, outside, note}. The note is one line for the day log.
var name = msg.h.asset_name;

var total = msg.utilRows.reduce(function (sum, x) {
  return sum + (x.total_time_total || 0);
}, 0);
var note = name + ': ' + msg.planRows.length + ' plan rows, ' +
  msg.lossRows.length + ' stops, sum total_time ' +
  (total / 60).toFixed(2) + ' h';
if (msg.droppedStops) {
  note += ', ' + msg.droppedStops + ' stops outside the day ignored';
}

msg.payload = {
  assetId: msg.asset.id,
  name: name,
  failed: null,
  skipped: null,
  planRows: msg.planRows,
  utilRows: msg.utilRows,
  lossRows: msg.lossRows,
  unmapped: msg.unmapped,
  outside: msg.droppedStops,
  note: note
};
delete msg.planRows;
delete msg.utilRows;
delete msg.lossRows;
delete msg.droppedStops;
delete msg.unmapped;
delete msg.shiftRules;
return msg;

// Collects the asset results that the join delivered.
// In: msg.payload = array of asset results. Out: msg.planRows, msg.utilRows,
// msg.lossRows and msg.summary = {failed, notes, skipped, unmapped}.
var results = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var failed = [];
var notes = [];
var skipped = (msg.planSkipped || []).slice();
var unmapped = [];
var planRows = [];
var utilRows = [];
var lossRows = [];

results.forEach(function (r) {
  if (!r) {
    return;
  }
  if (r.failed) {
    failed.push(r.failed);
  }
  if (r.skipped) {
    skipped.push(r.skipped);
  }
  if (r.note) {
    notes.push(r.note);
  }
  (r.unmapped || []).forEach(function (u) {
    if (unmapped.indexOf(u) < 0) {
      unmapped.push(u);
    }
  });
  planRows = planRows.concat(r.planRows || []);
  utilRows = utilRows.concat(r.utilRows || []);
  lossRows = lossRows.concat(r.lossRows || []);
});

msg.summary = {
  failed: failed,
  notes: notes,
  skipped: skipped,
  unmapped: unmapped
};
msg.planRows = planRows;
msg.utilRows = utilRows;
msg.lossRows = lossRows;
delete msg.payload;
delete msg.planSkipped;
return msg;

// Decides what happens with the day.
// In: msg.planRows, utilRows, lossRows and summary. Out 1: the message goes
// on to node 6.3 (write). Out 2: a log line (failed, nothing to write, dry
// run). Any failed asset means nothing is written for the day.
var cfg = flow.get('cfg');
var day = msg.day;
var summary = msg.summary;
var notes = summary.notes.join(' | ');
var sizes = 'pbi_plan_opt ' + msg.planRows.length + ' rows, ' +
  'pbi_time_utilisation ' + msg.utilRows.length + ' rows, ' +
  'pbi_daily_losses ' + msg.lossRows.length + ' rows';
var empty = !msg.planRows.length && !msg.lossRows.length;

// Text added to the end of every log line.
var tail = '';
if (summary.skipped.length) {
  tail += ' | skipped: ' + summary.skipped.join('; ');
}
if (summary.unmapped.length) {
  tail += ' | KPI without column: ' + summary.unmapped.join(', ');
}

function logOnly(text) {
  var line = { topic: 'log', payload: day + ' [' + msg.mode + '] ' + text };
  return [null, line];
}

if (summary.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: day + ' FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + summary.failed.join(' | ') + tail
  );
}
if (empty) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: day + ' nothing to write'
  });
  return logOnly(notes + ' | NOTHING TO WRITE' + tail);
}
if (cfg.dryRun) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: day + ' dry run ' + msg.planRows.length + '/' + msg.lossRows.length
  });
  return logOnly(notes + ' | DRY RUN: ' + sizes + tail);
}

msg.writeNote = notes + ' | WRITING ' + sizes + tail;
return [msg, null];

// Builds one message per table for the parquet nodes.
// In: msg.planRows, msg.utilRows, msg.lossRows and msg.writeNote.
// Out 1: pbi_plan_opt. Out 2: pbi_time_utilisation. Out 3: pbi_daily_losses.
// Out 4: log line. A table without rows sends nothing.
var day = msg.day;

function table(name, rows) {
  if (!rows.length) {
    return null;
  }
  return { topic: name, day: day, payload: rows };
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: day + ' ' + msg.planRows.length + '/' + msg.lossRows.length
});
var line = {
  topic: 'log',
  payload: day + ' [' + msg.mode + '] ' + msg.writeNote
};
return [
  table('pbi_plan_opt', msg.planRows),
  table('pbi_time_utilisation', msg.utilRows),
  table('pbi_daily_losses', msg.lossRows),
  line
];

// Sets the file path in the data lake for the table pbi_plan_opt.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The text YYYY-MM-DD
// in the path becomes the production day, so a rerun replaces the file.
var cfg = flow.get('cfg');
msg.path = cfg.paths.pbi_plan_opt.replace('YYYY-MM-DD', msg.day);
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the file path in the data lake for the table pbi_time_utilisation.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The text YYYY-MM-DD
// in the path becomes the production day, so a rerun replaces the file.
var cfg = flow.get('cfg');
msg.path = cfg.paths.pbi_time_utilisation.replace('YYYY-MM-DD', msg.day);
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the file path in the data lake for the table pbi_daily_losses.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The text YYYY-MM-DD
// in the path becomes the production day, so a rerun replaces the file.
var cfg = flow.get('cfg');
msg.path = cfg.paths.pbi_daily_losses.replace('YYYY-MM-DD', msg.day);
msg.filename = msg.path.split('/').pop();
return msg;

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'pbi-hull';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'pbi-hull';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
flow.set('logDone', done.slice(-KEEP_IDS));

msg.payload = old + lines.join('\n') + '\n';
msg.path = path;
delete msg.logRows;
return msg;
